def calculateMaxProfit(price, futurePrice, principle):
    n = len(price)
    dp = [0] * (principle + 1)
    for i in range(n):
        profit = futurePrice[i] - price[i]
        if profit <= 0 or price[i] > principle:
            continue
        for w in range(principle, price[i] - 1, -1):
            dp[w] = max(dp[w], dp[w - price[i]] + profit)
    return dp[principle]

class Solution {
    public int calculateMaxProfit(int[] price, int[] futurePrice, int principle) {
        int n = price.length;
        int[] dp = new int[principle + 1];
        for (int i = 0; i < n; i++) {
            int profit = futurePrice[i] - price[i];
            if (profit <= 0 || price[i] > principle) continue;
            for (int w = principle; w >= price[i]; w--) {
                dp[w] = Math.max(dp[w], dp[w - price[i]] + profit);
            }
        }
        return dp[principle];
    }
}

